package com.smartmanager.nativeapp;
import android.app.*;import android.content.Intent;import java.util.ArrayList;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;
public final class TemplateActivity extends Activity {private LinearLayout p;private EditText name,rows,cols,margin,gap;private CheckBox user,password,profile,serial;private TemplateStore store;private String imageUri="";private String currentId="default";@Override public void onCreate(Bundle b){super.onCreate(b);store=new TemplateStore(this);CardTemplate t=store.get();currentId=t.id;imageUri=t.imageUri;p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(18,20,18,30);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);p.addView(txt("قالب طباعة الكروت",24));Spinner chooser=new Spinner(this);ArrayList<String> labels=new ArrayList<>();for(CardTemplate x:store.all())labels.add(x.name);chooser.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));chooser.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){CardTemplate x=store.all().get(pos);currentId=x.id;imageUri=x.imageUri;if(name!=null)name.setText(x.name);}});p.addView(chooser);Button newTemplate=new Button(this);newTemplate.setText("قالب جديد");newTemplate.setOnClickListener(v->{currentId=java.util.UUID.randomUUID().toString();name.setText("قالب جديد");imageUri="";});p.addView(newTemplate);name=f("اسم القالب",t.name);rows=f("الصفوف على A4",String.valueOf(t.rows));cols=f("الأعمدة على A4",String.valueOf(t.columns));margin=f("الهامش بالنقاط",String.valueOf(t.margin));gap=f("الفجوة بالنقاط",String.valueOf(t.gap));user=check("اسم المستخدم",t.showUser);password=check("كلمة المرور",t.showPassword);profile=check("الباقة",t.showProfile);serial=check("الرقم التسلسلي",t.showSerial);Button pick=new Button(this);pick.setText("اختيار خلفية");pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,77);});p.addView(pick);Button save=new Button(this);save.setText("حفظ القالب");save.setOnClickListener(v->save());p.addView(save);Button del=new Button(this);del.setText("حذف القالب الحالي");del.setOnClickListener(v->{if("default".equals(currentId))Toast.makeText(this,"لا يمكن حذف القالب الافتراضي",Toast.LENGTH_LONG).show();else new AlertDialog.Builder(this).setTitle("تأكيد حذف القالب").setMessage("لن تتأثر دفعات الكروت القديمة").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{if(store.remove(currentId)){Toast.makeText(this,"تم حذف القالب",Toast.LENGTH_SHORT).show();finish();}else Toast.makeText(this,"تعذر حذف القالب",Toast.LENGTH_LONG).show();}).show();});p.addView(del);p.addView(txt("اختيار الخلفية والمعاينة المرئية الكاملة مؤجلان حتى دمج محرك الرسم المشترك واختباره.",13));}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==77&&c==RESULT_OK&&d!=null&&d.getData()!=null){imageUri=d.getData().toString();try{getContentResolver().takePersistableUriPermission(d.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}}
 private void save(){try{CardTemplate t=new CardTemplate(currentId,name.getText().toString(),imageUri,595,842,Integer.parseInt(rows.getText().toString()),Integer.parseInt(cols.getText().toString()),Integer.parseInt(margin.getText().toString()),Integer.parseInt(gap.getText().toString()),user.isChecked(),password.isChecked(),profile.isChecked(),serial.isChecked());if(store.save(t))Toast.makeText(this,"تم حفظ القالب",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"تحقق من الإعدادات",Toast.LENGTH_LONG).show();}}private EditText f(String h,String v){EditText e=new EditText(this);e.setHint(h);e.setText(v);e.setSingleLine(true);p.addView(e);return e;}private CheckBox check(String s,boolean v){CheckBox c=new CheckBox(this);c.setText(s);c.setChecked(v);p.addView(c);return c;}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}}
